WITH target AS ( SELECT c.*, i.configured_start_block FROM insights_competitions c JOIN perps_indexer_state i ON i.chain_id = c.chain_id AND i.release_router = c.release_router  AND i.indexer_name = ((CASE WHEN c.slug = 'testnet-trading-2026' THEN 'perps-history-costs-v1:' ELSE 'perps-history-costs-v2:finalized-abi3:' END) || c.release_router)  AND i.configured_start_block IS NOT NULL AND i.last_indexed_block_hash IS NOT NULL  AND split_part(c.release_manifest, '|', 12) ~ '^[1-9][0-9]*$'  AND i.configured_start_block = split_part(c.release_manifest, '|', 12)::bigint WHERE c.slug = ? AND c.finalized = FALSE ), start_batch AS ( SELECT b.* FROM insights_snapshot_batches b JOIN target t ON t.slug = b.competition_slug WHERE b.snapshot_kind = 'start' AND t.start_block IS NOT NULL AND b.block_number = t.start_block - 1 AND t.start_snapshot_block_hash IS NOT NULL AND LOWER(b.block_hash) = LOWER(t.start_snapshot_block_hash) AND b.participant_count = (SELECT COUNT(*) FROM insights_competition_participants p WHERE p.competition_slug = t.slug) ORDER BY b.published_at DESC LIMIT 1 ), baseline AS ( SELECT s.wallet, GREATEST(0, CASE WHEN s.has_open_position THEN s.signed_net_equity_usdc  ELSE s.terminal_reachable_usdc END + s.trader_claims_usdc) AS value_usdc, s.has_open_position, COALESCE(NULLIF(s.raw_data->>'pendingOrderCount', '')::integer, 0) AS pending_order_count, s.block_number AS baseline_block FROM insights_account_snapshots s JOIN start_batch b ON b.competition_slug = s.competition_slug AND b.snapshot_kind = s.snapshot_kind  AND b.block_number = s.block_number AND LOWER(b.block_hash) = LOWER(s.block_hash) ), participants AS ( SELECT p.wallet, p.trader_reference, b.value_usdc, COALESCE(b.has_open_position, FALSE) AS has_open_position, COALESCE(b.pending_order_count, 0) AS pending_order_count, b.baseline_block, t.* FROM insights_competition_participants p JOIN target t ON t.slug = p.competition_slug LEFT JOIN baseline b ON b.wallet = p.wallet ), canonical_mints AS ( SELECT p.wallet, x.tx_hash, x.block_number, x.block_hash, x.tx_index, x.log_index FROM participants p JOIN testnet_faucet_claims fc  ON LOWER(fc.address) = LOWER(p.wallet) AND LOWER(fc.token_address) = LOWER(p.usdc_address) JOIN perps_usdc_transfers x ON x.chain_id = p.chain_id AND x.release_router = p.release_router  AND LOWER(x.token_address) = LOWER(p.usdc_address) AND LOWER(x.tx_hash) = LOWER(fc.tx_hash)  AND x.block_number = fc.mint_block_number AND x.from_address = '0x0000000000000000000000000000000000000000'  AND LOWER(x.to_address) = LOWER(p.wallet) AND x.amount = p.starting_balance_usdc WHERE fc.status = 'success' AND fc.amount = p.starting_balance_usdc  AND NULLIF(BTRIM(fc.tx_hash), '') IS NOT NULL AND fc.mint_block_number IS NOT NULL  AND x.block_number >= p.configured_start_block AND x.timestamp < p.score_cutoff_timestamp ), mint_counts AS ( SELECT p.wallet, COUNT(m.wallet) AS mint_count FROM participants p LEFT JOIN canonical_mints m ON m.wallet = p.wallet GROUP BY p.wallet ), first_mint AS ( SELECT DISTINCT ON (wallet) wallet, block_number, tx_index, log_index FROM canonical_mints ORDER BY wallet, block_number, tx_index, log_index ), flow_rows AS ( SELECT p.wallet, a.activity_type, a.amount_usdc, a.tx_hash, a.block_number, a.block_hash, EXISTS (SELECT 1 FROM aa_close_assistance g WHERE g.verified AND g.chain_id=a.chain_id AND g.router=a.release_router AND g.account=a.account AND g.transaction_hash=LOWER(a.tx_hash) AND g.block_number=a.block_number AND g.block_hash=LOWER(a.block_hash) AND g.deposit_log_index=a.log_index AND g.amount_usdc=a.amount_usdc AND a.activity_type='Deposit') AS close_assistance, a.tx_index, a.log_index, a.timestamp, (SELECT MIN(x.log_index) FROM perps_usdc_transfers x  WHERE x.chain_id = p.chain_id AND x.release_router = p.release_router   AND LOWER(x.token_address) = LOWER(p.usdc_address) AND x.tx_hash = LOWER(a.tx_hash)   AND x.block_number = a.block_number AND x.block_hash = LOWER(a.block_hash) AND x.amount = a.amount_usdc   AND ((a.activity_type = 'Deposit' AND LOWER(x.from_address) = LOWER(p.wallet)    AND LOWER(x.to_address) = LOWER(p.margin_clearinghouse_address)) OR (a.activity_type = 'Withdraw'    AND LOWER(x.from_address) = LOWER(p.margin_clearinghouse_address) AND LOWER(x.to_address) = LOWER(p.wallet))))  AS transfer_log_index, (LOWER(COALESCE(a.contract_address, '')) = LOWER(p.margin_clearinghouse_address)  AND LOWER(COALESCE(a.data->>'asset', '')) = LOWER(p.usdc_address) AND a.amount_usdc > 0  AND (SELECT COUNT(*) FROM perps_usdc_transfers x WHERE x.chain_id = p.chain_id    AND x.release_router = p.release_router AND LOWER(x.token_address) = LOWER(p.usdc_address)    AND x.tx_hash = LOWER(a.tx_hash) AND x.block_number = a.block_number AND x.block_hash = LOWER(a.block_hash)    AND x.amount = a.amount_usdc AND ((a.activity_type = 'Deposit' AND LOWER(x.from_address) = LOWER(p.wallet)      AND LOWER(x.to_address) = LOWER(p.margin_clearinghouse_address)) OR (a.activity_type = 'Withdraw'      AND LOWER(x.from_address) = LOWER(p.margin_clearinghouse_address) AND LOWER(x.to_address) = LOWER(p.wallet)))) = 1  AND (SELECT COUNT(*) FROM perps_account_activity peer WHERE peer.chain_id = p.chain_id    AND peer.release_router = p.release_router AND peer.account = p.wallet AND peer.activity_type = a.activity_type    AND peer.tx_hash = a.tx_hash AND peer.block_number = a.block_number AND peer.block_hash = a.block_hash    AND peer.amount_usdc = a.amount_usdc AND LOWER(COALESCE(peer.contract_address, '')) = LOWER(p.margin_clearinghouse_address)    AND LOWER(COALESCE(peer.data->>'asset', '')) = LOWER(p.usdc_address)) = 1 OR EXISTS (SELECT 1 FROM aa_close_assistance g WHERE g.verified AND g.chain_id=a.chain_id AND g.router=a.release_router AND g.account=a.account AND g.transaction_hash=LOWER(a.tx_hash) AND g.block_number=a.block_number AND g.block_hash=LOWER(a.block_hash) AND g.deposit_log_index=a.log_index AND g.amount_usdc=a.amount_usdc AND a.activity_type='Deposit')) AS verified FROM participants p JOIN perps_account_activity a ON a.chain_id = p.chain_id  AND a.release_router = p.release_router AND a.account = p.wallet WHERE a.activity_type IN ('Deposit', 'Withdraw') AND a.block_number >= p.configured_start_block  AND a.timestamp < p.score_cutoff_timestamp ), flow_summary AS ( SELECT p.wallet, COUNT(*) FILTER (WHERE f.block_number <= p.baseline_block) AS baseline_flow_count, COUNT(*) FILTER (WHERE f.activity_type = 'Deposit' AND NOT f.close_assistance) AS deposit_count, COUNT(*) FILTER (WHERE f.activity_type = 'Deposit' AND NOT f.close_assistance AND f.block_number <= p.baseline_block) AS baseline_deposit_count, COALESCE(SUM(CASE WHEN f.close_assistance THEN 0 WHEN f.activity_type = 'Deposit' THEN f.amount_usdc ELSE -f.amount_usdc END)  FILTER (WHERE f.verified AND f.block_number <= p.baseline_block), 0) AS baseline_flow_net, COUNT(*) FILTER (WHERE NOT f.verified) AS unverified_flow_count, COUNT(*) FILTER (WHERE f.verified AND f.activity_type = 'Deposit' AND f.amount_usdc = p.starting_balance_usdc  AND mc.mint_count = 1 AND ROW(f.block_number, f.tx_index, f.log_index) > ROW(m.block_number, m.tx_index, m.log_index)  AND f.block_number <= p.baseline_block) AS baseline_official_count, COALESCE(SUM(f.amount_usdc) FILTER (WHERE f.verified AND f.activity_type = 'Deposit'  AND f.amount_usdc = p.starting_balance_usdc AND mc.mint_count = 1  AND ROW(f.block_number, f.tx_index, f.log_index) > ROW(m.block_number, m.tx_index, m.log_index)  AND f.block_number <= p.baseline_block), 0) AS baseline_official_amount, COUNT(*) FILTER (WHERE f.verified AND f.activity_type = 'Deposit' AND f.amount_usdc = p.starting_balance_usdc  AND mc.mint_count = 1 AND ROW(f.block_number, f.tx_index, f.log_index) > ROW(m.block_number, m.tx_index, m.log_index)  AND f.block_number > p.baseline_block) AS post_official_count, COALESCE(SUM(f.amount_usdc) FILTER (WHERE f.verified AND f.activity_type = 'Deposit'  AND f.amount_usdc = p.starting_balance_usdc AND mc.mint_count = 1  AND ROW(f.block_number, f.tx_index, f.log_index) > ROW(m.block_number, m.tx_index, m.log_index)  AND f.block_number > p.baseline_block), 0) AS post_official_amount, COUNT(*) FILTER (WHERE f.activity_type = 'Deposit' AND NOT f.close_assistance AND mc.mint_count = 1  AND ROW(f.block_number, f.tx_index, f.log_index) <= ROW(m.block_number, m.tx_index, m.log_index)) AS pre_mint_deposit_count FROM participants p LEFT JOIN flow_rows f ON f.wallet = p.wallet LEFT JOIN mint_counts mc ON mc.wallet = p.wallet LEFT JOIN first_mint m ON m.wallet = p.wallet GROUP BY p.wallet, p.baseline_block, p.starting_balance_usdc, mc.mint_count,  m.block_number, m.tx_index, m.log_index ), running_funding AS ( SELECT wallet, SUM(CASE WHEN close_assistance THEN 0 WHEN activity_type = 'Deposit' THEN amount_usdc ELSE -amount_usdc END)  OVER (PARTITION BY wallet ORDER BY block_number, tx_index, log_index) AS running_net FROM flow_rows WHERE verified ), funding_cap AS (SELECT wallet, COALESCE(MAX(running_net), 0) AS max_net_amount FROM running_funding GROUP BY wallet), allocation AS ( SELECT DISTINCT ON (f.wallet) f.wallet, f.block_number, f.tx_index, f.log_index FROM flow_rows f JOIN participants p ON p.wallet = f.wallet JOIN mint_counts mc ON mc.wallet = f.wallet JOIN first_mint m ON m.wallet = f.wallet WHERE f.verified AND f.activity_type = 'Deposit'  AND f.amount_usdc = p.starting_balance_usdc AND mc.mint_count = 1  AND ROW(f.block_number, f.tx_index, f.log_index) > ROW(m.block_number, m.tx_index, m.log_index) ORDER BY f.wallet, f.block_number, f.tx_index, f.log_index ), first_trade AS ( SELECT DISTINCT ON (p.wallet) p.wallet, a.block_number, a.tx_index, a.log_index FROM participants p JOIN perps_account_activity a ON a.chain_id = p.chain_id AND a.release_router = p.release_router  AND a.account = p.wallet AND a.activity_type IN ('Open', 'Close') AND COALESCE(a.size_delta, 0) <> 0 WHERE a.timestamp >= p.start_timestamp AND a.timestamp < p.score_cutoff_timestamp ORDER BY p.wallet, a.block_number, a.tx_index, a.log_index ), registration_audit AS ( SELECT p.wallet, (p.registration_close_timestamp IS NULL OR r.registration_id IS NOT NULL) AS verified_registration FROM participants p LEFT JOIN insights_registration_applications r ON r.competition_slug = p.slug  AND r.registration_id::text = p.trader_reference AND r.status = 'completed' AND r.trading_account = p.wallet ), invalid_inbound AS ( SELECT p.wallet, COUNT(*) AS invalid_count FROM participants p JOIN perps_usdc_transfers x  ON x.chain_id = p.chain_id AND x.release_router = p.release_router  AND LOWER(x.token_address) = LOWER(p.usdc_address) AND LOWER(x.to_address) = LOWER(p.wallet) WHERE x.amount > 0 AND x.block_number >= p.configured_start_block AND x.timestamp < p.score_cutoff_timestamp  AND NOT (EXISTS (SELECT 1 FROM canonical_mints m WHERE m.wallet = p.wallet AND m.tx_hash = x.tx_hash    AND m.block_number = x.block_number AND m.block_hash = x.block_hash AND m.log_index = x.log_index)   OR (SELECT COUNT(*) FROM flow_rows f WHERE f.wallet = p.wallet AND f.verified    AND f.activity_type = 'Withdraw' AND f.tx_hash = x.tx_hash AND f.block_number = x.block_number    AND f.block_hash = x.block_hash AND f.amount_usdc = x.amount AND f.transfer_log_index = x.log_index    AND LOWER(x.from_address) = LOWER(p.margin_clearinghouse_address)) = 1) GROUP BY p.wallet ), premature_outbound AS ( SELECT p.wallet, COUNT(*) AS invalid_count FROM participants p JOIN allocation al ON al.wallet = p.wallet JOIN first_mint m ON m.wallet = p.wallet JOIN perps_usdc_transfers x ON x.chain_id = p.chain_id AND x.release_router = p.release_router  AND LOWER(x.token_address) = LOWER(p.usdc_address) AND LOWER(x.from_address) = LOWER(p.wallet)  AND ROW(x.block_number, x.tx_index, x.log_index) > ROW(m.block_number, m.tx_index, m.log_index)  AND ROW(x.block_number, x.tx_index, x.log_index) < ROW(al.block_number, al.tx_index, al.log_index) WHERE x.amount > 0 AND NOT EXISTS (SELECT 1 FROM flow_rows f WHERE f.wallet = p.wallet AND f.verified  AND f.activity_type = 'Deposit' AND f.tx_hash = x.tx_hash AND f.block_number = x.block_number  AND f.block_hash = x.block_hash AND f.amount_usdc = x.amount AND f.transfer_log_index = x.log_index  AND LOWER(x.to_address) = LOWER(p.margin_clearinghouse_address)) GROUP BY p.wallet ), facts AS ( SELECT p.wallet, p.value_usdc, p.has_open_position, p.pending_order_count, p.starting_balance_usdc, COALESCE(mc.mint_count, 0) AS mint_count, COALESCE(fs.baseline_flow_count, 0) AS baseline_flow_count, COALESCE(fs.deposit_count, 0) AS deposit_count, COALESCE(fs.baseline_deposit_count, 0) AS baseline_deposit_count, COALESCE(fs.baseline_flow_net, 0) AS baseline_flow_net, COALESCE(fs.unverified_flow_count, 0) AS unverified_flow_count, COALESCE(fs.baseline_official_count, 0) AS baseline_official_count, COALESCE(fs.baseline_official_amount, 0) AS baseline_official_amount, COALESCE(fs.post_official_count, 0) AS post_official_count, COALESCE(fs.post_official_amount, 0) AS post_official_amount, COALESCE(fs.pre_mint_deposit_count, 0) AS pre_mint_deposit_count, COALESCE(cap.max_net_amount, 0) AS max_net_amount, COALESCE(ii.invalid_count, 0) AS invalid_inbound_count, COALESCE(po.invalid_count, 0) AS premature_outbound_count, al.block_number AS allocation_block, al.tx_index AS allocation_tx, al.log_index AS allocation_log, tr.block_number AS trade_block, tr.tx_index AS trade_tx, tr.log_index AS trade_log, COALESCE(ra.verified_registration, FALSE) AS verified_registration FROM participants p LEFT JOIN mint_counts mc ON mc.wallet = p.wallet LEFT JOIN flow_summary fs ON fs.wallet = p.wallet LEFT JOIN funding_cap cap ON cap.wallet = p.wallet LEFT JOIN invalid_inbound ii ON ii.wallet = p.wallet LEFT JOIN premature_outbound po ON po.wallet = p.wallet LEFT JOIN allocation al ON al.wallet = p.wallet LEFT JOIN first_trade tr ON tr.wallet = p.wallet LEFT JOIN registration_audit ra ON ra.wallet = p.wallet ), computed AS (SELECT wallet, TO_JSONB(ARRAY_REMOVE(ARRAY[ CASE WHEN value_usdc IS NULL THEN 'baseline_unavailable' END, CASE WHEN NOT verified_registration THEN 'missing_verified_registration' END, CASE WHEN has_open_position THEN 'baseline_open_position' END, CASE WHEN pending_order_count > 0 THEN 'baseline_pending_orders' END, CASE WHEN value_usdc IS NOT NULL AND value_usdc NOT IN (0, starting_balance_usdc) THEN 'invalid_starting_bankroll' END, CASE WHEN mint_count <> 1 THEN 'official_mint_count_invalid' END, CASE WHEN deposit_count <> 1 THEN 'unofficial_capital_used' END, CASE WHEN pre_mint_deposit_count > 0 THEN 'deposit_before_official_mint' END, CASE WHEN value_usdc = starting_balance_usdc AND baseline_official_count <> 1 THEN 'baseline_official_allocation_count_invalid' END, CASE WHEN value_usdc = starting_balance_usdc AND baseline_official_amount <> starting_balance_usdc THEN 'baseline_official_allocation_amount_invalid' END, CASE WHEN value_usdc = starting_balance_usdc AND baseline_flow_net <> starting_balance_usdc THEN 'baseline_funding_flow_mismatch' END, CASE WHEN value_usdc = starting_balance_usdc AND post_official_count > 0 THEN 'unexpected_official_deposit' END, CASE WHEN value_usdc = 0 AND (baseline_flow_count <> 0 OR baseline_deposit_count <> 0) THEN 'unexpected_prebaseline_funding' END, CASE WHEN value_usdc = 0 AND baseline_flow_net <> 0 THEN 'zero_baseline_funding_flow_mismatch' END, CASE WHEN value_usdc = 0 AND post_official_count <> 1 THEN 'official_allocation_count_invalid' END, CASE WHEN value_usdc = 0 AND post_official_amount <> starting_balance_usdc THEN 'official_allocation_amount_invalid' END, CASE WHEN value_usdc = 0 AND trade_block IS NOT NULL  AND ROW(allocation_block, allocation_tx, allocation_log) >= ROW(trade_block, trade_tx, trade_log)  THEN 'official_allocation_not_before_trading' END, CASE WHEN unverified_flow_count > 0 THEN 'unverified_funding_flow' END, CASE WHEN premature_outbound_count > 0 THEN 'official_funds_left_before_allocation' END, CASE WHEN max_net_amount > starting_balance_usdc THEN 'funding_capacity_exceeded' END ]::TEXT[], NULL)) AS flags FROM facts) UPDATE insights_competition_participants p SET integrity_flags = c.flags, updated_at = NOW() FROM computed c, target t WHERE p.competition_slug = t.slug AND p.wallet = c.wallet
